				}
			});
		}

		/**
		 * Init each map (coupled with MapHelper)
		 * Calls another function google_maps_init_each_in_registry()
		 * after checking for necessary JS dependencies
		 */ 
		function google_maps_init() {

			var src_maplabels 	   = "//electionstats.state.ma.us/js/google-maplabel.js";
			var src_canvas_for_ie  = "//electionstats.state.ma.us/js/excanvas.compiled.js";
			var src_canvas_text_for_ie  = "//electionstats.state.ma.us/js/canvas.text.js";

			// If browser does NOT have canvas HTML5, then first load that shiv library (IE8-)
			if(!Modernizr.canvas) { 
				$.getScript(src_canvas_for_ie, function() {
					$.getScript(src_canvas_text_for_ie, function() {
						$.getScript(src_maplabels, function() { google_maps_init_each_in_registry(); });
					});
				});
			} else {
				// Add in library for map labels, and upon the script loading, fire the rest of the init routine.
				$.getScript(src_maplabels, function() { google_maps_init_each_in_registry(); });

			}

		}




